"""Numba-CUDA fused kernel (generated by :mod:`pylbm.codegen`, one thread per node)."""

from __future__ import annotations

from typing import Any

import numpy as np

from ..codegen import load, spec_for
from ._fused import FusedSolver, cuda_ok

try:
    if not hasattr(np, "row_stack"):  # numba-cuda 0.x still references np.row_stack
        np.row_stack = np.vstack  # type: ignore[attr-defined]
    from numba import cuda

    _HAVE = True
except Exception:  # pragma: no cover
    _HAVE = False


class NumbaFused(FusedSolver):
    """``numba.cuda.jit`` kernel, 2D/3D launch grid, fp32, two buffers."""

    backend = "numba"
    variant = "fused"
    description = "Numba-CUDA fused stream+collide+BC, pull, SoA, two buffers"
    THREADS = (128, 1, 1)

    @classmethod
    def available(cls) -> tuple[bool, str]:
        if not _HAVE:
            return False, "numba-cuda not installed"
        ok, why = cuda_ok()
        if not ok:
            return ok, why
        try:
            if not cuda.is_available():
                return False, "numba sees no CUDA device"
        except Exception as e:  # pragma: no cover
            return False, str(e)
        return True, ""

    def _compile(self) -> None:
        p = self.problem
        pats = ("aa-odd", "aa-even") if self.aa else ("ab",)
        self.kernels = {pat: load(spec_for(p, self.storage, pat), "numba").lbm_kernel
                        for pat in pats}
        shp = tuple(p.shape) + (1,) * (3 - p.dim)
        tx = self.THREADS[0]
        self.blocks = ((shp[0] + tx - 1) // tx, shp[1], shp[2])
        if p.dim == 2:
            self.blocks, self.threads = self.blocks[:2], self.THREADS[:2]
        else:
            self.threads = self.THREADS
        a = self.scalar_args()
        ints, floats = a[:4], a[4:]
        self.args = tuple(np.int64(v) for v in ints) + tuple(np.float32(v) for v in floats)
        self._views: dict[int, Any] = {}

    def _view(self, t: Any) -> Any:
        key = t.data_ptr()
        if key not in self._views:
            self._views[key] = cuda.as_cuda_array(t)
        return self._views[key]

    def _launch(self, which: str, src: Any, dst: Any) -> None:
        self.kernels[which][self.blocks, self.threads](self._view(src), self._view(dst),
                                                       *self.args)
